function u(e){let a=Number.POSITIVE_INFINITY;for(const i of e||[]){const n=Number(i?.count),t=i?.balance;!Number.isFinite(n)||n<=0||t==null||!Number.isFinite(Number(t))||(a=Math.min(a,Math.floor(Number(t)/n)))}return a}function r(e){const a=e.cap??9999,i=e.limitRemaining;let n=BigInt(Math.max(0,Math.floor(Math.min(a,i??a))));for(const t of e.costs||[]){if(t.count==null||t.balance==null)return 0;const c=BigInt(t.count);if(c<=0n)return 0;const o=BigInt(t.balance)/c;o<n&&(n=o)}return Number(n<0n?0n:n)}export{u as a,r as p};
